CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE SCHEMA IF NOT EXISTS lbt_development;
SET search_path TO lbt_development,public;
CREATE TABLE principals(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('scheduler','employee','reviewer')), active boolean NOT NULL DEFAULT true);
CREATE TABLE facilities(id text PRIMARY KEY, company_id uuid NOT NULL, label text NOT NULL);
CREATE TABLE equipment(id text PRIMARY KEY, facility_id text NOT NULL REFERENCES facilities, label text NOT NULL);
CREATE TABLE cycles(id uuid PRIMARY KEY, equipment_id text NOT NULL REFERENCES equipment, due_date date NOT NULL, version int NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','complete')), UNIQUE(equipment_id,due_date));
CREATE TABLE resources(id text PRIMARY KEY, label text NOT NULL, valid_until timestamptz NOT NULL);
CREATE TABLE visits(id uuid PRIMARY KEY, cycle_id uuid NOT NULL REFERENCES cycles, ordinal int NOT NULL CHECK(ordinal IN(1,2)), assignee uuid NOT NULL REFERENCES principals, starts_at timestamptz, ends_at timestamptz, instrument_id text REFERENCES resources, executed boolean NOT NULL DEFAULT false, UNIQUE(cycle_id,ordinal), CHECK((starts_at IS NULL AND ends_at IS NULL AND instrument_id IS NULL) OR (starts_at IS NOT NULL AND ends_at>starts_at AND instrument_id IS NOT NULL)));
CREATE TABLE reservations(visit_id uuid NOT NULL REFERENCES visits, resource_id text NOT NULL, occupied tstzrange NOT NULL, PRIMARY KEY(visit_id,resource_id), CHECK(NOT isempty(occupied) AND lower_inc(occupied) AND NOT upper_inc(occupied)), EXCLUDE USING gist(resource_id WITH =, occupied WITH &&));
CREATE TABLE reports(id uuid PRIMARY KEY, visit_id uuid NOT NULL REFERENCES visits, revision int NOT NULL, author uuid NOT NULL REFERENCES principals, body bytea NOT NULL, sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(visit_id,revision));
CREATE TABLE decisions(id uuid PRIMARY KEY, report_id uuid UNIQUE NOT NULL REFERENCES reports, reviewer uuid NOT NULL REFERENCES principals, approved boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cycle_id uuid NOT NULL REFERENCES cycles, actor uuid NOT NULL REFERENCES principals, command text NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY, cycle_id uuid NOT NULL REFERENCES cycles, event_sequence bigint UNIQUE NOT NULL REFERENCES events, state text NOT NULL DEFAULT 'captured' CHECK(state='captured'));
CREATE TABLE receipts(actor uuid NOT NULL REFERENCES principals, key text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, PRIMARY KEY(actor,key));
CREATE FUNCTION immutable_evidence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Evidence is append-only'; END $$;
CREATE TRIGGER reports_immutable BEFORE UPDATE OR DELETE ON reports FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER decisions_immutable BEFORE UPDATE OR DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON events FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER reports_no_truncate BEFORE TRUNCATE ON reports EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER decisions_no_truncate BEFORE TRUNCATE ON decisions EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER events_no_truncate BEFORE TRUNCATE ON events EXECUTE FUNCTION immutable_evidence();
